    steps = [f'讀題定位：圈出「{tag}」與題目要求的資源、區位、成本、環境或治理條件。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」最完整地支持綠能發展條件判讀。', '排除誘答：檢查是否只看裝置量、單日數據、單一利益或把占比直接當成成效。', '結論回查：確認各指標的分母、期間與適用範圍一致，並保留長期監測需求。']
    return {'id': f'question-social-content-geo-bh-iv-4-{i}', 'subject': 'social', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-social-content-geo-bh-iv-4'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': SOURCES[0][0], 'sourceLocator': '公立國中社會科公開試題；研究綠能區位、能源供需、環境代價與公共決策的能力方向。', 'authoringNote': '依官方課綱 KG 與三個公立學校公開來源的題型／能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-09', 'lessonId': 'lesson-social-content-geo-bh-iv-4', 'examPatternRefs': refs, 'solutionStrategy': '先分辨能源資源、裝置容量、實際輸出與環境代價，再以多指標與生命週期比較。', 'solutionSteps': steps}

